UPDATE national_issue_templates SET title = replace(title, '{{inflationRate}}%', '{{inflationRate}}'), description = replace(description, '{{inflationRate}}%', '{{inflationRate}}'), "longDescription" = replace("longDescription", '{{inflationRate}}%', '{{inflationRate}}') WHERE slug IN ('workers_strike', 'unemployment_spike', 'inflation_spiral', 'recession_warning');
