INSERT INTO national_issue_templates ("id", "slug", "title", "description", "longDescription", "domain", "category", "tags", "baseSeverity", "baseUrgency", "deadlineDaysBase", "triggerConditions", "cooldownDays", "maxActivePerCountry", "responseOptions", "isActive", "updatedAt") VALUES ('routine_budget_priorities', 'routine_budget_priorities', 'Setting next year''s spending priorities', 'The finance ministry needs a steer on where {{countryName}}''s extra spending should go next year.', 'Revenue came in close to forecast, leaving a modest margin for new spending. {{ministerName}} has drawn up three options for the cabinet: invest in roads and utilities, put more into schools and clinics, or hold the money back and pay down debt.', 'economic', 'economic', '["routine","budget"]', 'low', 30, NULL, '{"field":"currentPopulation","op":">=","value":0}', 28, 1, '[{"id":"infrastructure","label":"Roads and utilities","description":"Fund repairs and upgrades to transport and utilities.","consequences":[{"targetModel":"Country","targetField":"infrastructureRating","operation":"add","value":2},{"targetModel":"Country","targetField":"totalDebtGDPRatio","operation":"add","value":0.5}],"previewEffects":{"economicImpact":"Better infrastructure, a little more debt"},"outcomeText":"Work crews start on the backlog of repairs. Commuters notice by the end of the year."},{"id":"services","label":"Schools and clinics","description":"Put the margin into teachers, nurses and equipment.","consequences":[{"targetModel":"Country","targetField":"publicApproval","operation":"add","value":2},{"targetModel":"Country","targetField":"literacyRate","operation":"add","value":0.5},{"targetModel":"Country","targetField":"totalDebtGDPRatio","operation":"add","value":0.5}],"previewEffects":{"publicApproval":2,"economicImpact":"A little more debt"},"outcomeText":"Class sizes shrink and clinic waiting lists shorten. Parents are pleased.","isAutoResolveDefault":true},{"id":"restraint","label":"Pay down debt","description":"Leave spending flat and use the margin to reduce borrowing.","consequences":[{"targetModel":"Country","targetField":"totalDebtGDPRatio","operation":"subtract","value":0.5},{"targetModel":"Country","targetField":"publicApproval","operation":"subtract","value":1}],"previewEffects":{"publicApproval":-1,"economicImpact":"Slightly lower debt"},"outcomeText":"Bond markets approve. Some voters wonder what the surplus was for."}]', true, CURRENT_TIMESTAMP) ON CONFLICT (slug) DO UPDATE SET "title" = EXCLUDED."title", "description" = EXCLUDED."description", "longDescription" = EXCLUDED."longDescription", "domain" = EXCLUDED."domain", "category" = EXCLUDED."category", "tags" = EXCLUDED."tags", "baseSeverity" = EXCLUDED."baseSeverity", "baseUrgency" = EXCLUDED."baseUrgency", "deadlineDaysBase" = EXCLUDED."deadlineDaysBase", "triggerConditions" = EXCLUDED."triggerConditions", "cooldownDays" = EXCLUDED."cooldownDays", "maxActivePerCountry" = EXCLUDED."maxActivePerCountry", "responseOptions" = EXCLUDED."responseOptions", "isActive" = EXCLUDED."isActive", "updatedAt" = EXCLUDED."updatedAt";
INSERT INTO national_issue_templates ("id", "slug", "title", "description", "longDescription", "domain", "category", "tags", "baseSeverity", "baseUrgency", "deadlineDaysBase", "triggerConditions", "cooldownDays", "maxActivePerCountry", "responseOptions", "isActive", "updatedAt") VALUES ('routine_public_works', 'routine_public_works', 'Choosing the next public works project', 'Planners in {{cityName}} have three projects ready and money for one of them.', 'The public works fund can carry one large project this year. Engineers favour a new rail link, the regional councils want their roads repaired, and housing campaigners are pressing for new homes beside a city park.', 'infrastructure', 'infrastructure', '["routine","public-works"]', 'low', 30, NULL, '{"field":"currentPopulation","op":">=","value":0}', 28, 1, '[{"id":"rail","label":"Build the rail link","description":"A long project that pays off for decades.","consequences":[{"targetModel":"Country","targetField":"infrastructureRating","operation":"add","value":3},{"targetModel":"Country","targetField":"totalDebtGDPRatio","operation":"add","value":1},{"targetModel":"Country","targetField":"actualGdpGrowth","operation":"add","value":0.1}],"previewEffects":{"economicImpact":"Growth and infrastructure up, debt up"},"outcomeText":"Ground is broken on the new line. Opening day is years away, but the work brings jobs now."},{"id":"roads","label":"Repair regional roads","description":"Spread the money across many smaller repairs.","consequences":[{"targetModel":"Country","targetField":"infrastructureRating","operation":"add","value":1},{"targetModel":"Country","targetField":"publicApproval","operation":"add","value":1}],"previewEffects":{"publicApproval":1},"outcomeText":"Potholes are filled across the provinces. Rural voters feel listened to.","isAutoResolveDefault":true},{"id":"housing","label":"Homes beside the park","description":"Build affordable homes and improve the park next to them.","consequences":[{"targetModel":"Country","targetField":"publicApproval","operation":"add","value":2},{"targetModel":"InternalStabilityMetrics","targetField":"socialCohesion","operation":"add","value":2},{"targetModel":"Country","targetField":"totalDebtGDPRatio","operation":"add","value":0.5}],"previewEffects":{"publicApproval":2,"stabilityImpact":"Positive"},"outcomeText":"Families move into the new homes by spring. The park fills up on weekends."}]', true, CURRENT_TIMESTAMP) ON CONFLICT (slug) DO UPDATE SET "title" = EXCLUDED."title", "description" = EXCLUDED."description", "longDescription" = EXCLUDED."longDescription", "domain" = EXCLUDED."domain", "category" = EXCLUDED."category", "tags" = EXCLUDED."tags", "baseSeverity" = EXCLUDED."baseSeverity", "baseUrgency" = EXCLUDED."baseUrgency", "deadlineDaysBase" = EXCLUDED."deadlineDaysBase", "triggerConditions" = EXCLUDED."triggerConditions", "cooldownDays" = EXCLUDED."cooldownDays", "maxActivePerCountry" = EXCLUDED."maxActivePerCountry", "responseOptions" = EXCLUDED."responseOptions", "isActive" = EXCLUDED."isActive", "updatedAt" = EXCLUDED."updatedAt";
INSERT INTO national_issue_templates ("id", "slug", "title", "description", "longDescription", "domain", "category", "tags", "baseSeverity", "baseUrgency", "deadlineDaysBase", "triggerConditions", "cooldownDays", "maxActivePerCountry", "responseOptions", "isActive", "updatedAt") VALUES ('routine_cabinet_appointment', 'routine_cabinet_appointment', 'A cabinet post to fill', 'A junior minister in {{countryName}} is retiring, and {{leaderName}} must choose a replacement.', 'The post is not glamorous, but it oversees a large department. The shortlist has three names: a long-serving civil servant, a loyal party figure, and an outside expert with no political record.', 'political', 'governance', '["routine","appointments"]', 'low', 30, NULL, '{"field":"currentPopulation","op":">=","value":0}', 28, 1, '[{"id":"civil_servant","label":"The career civil servant","description":"Someone who knows how the department works.","consequences":[{"targetModel":"GovernmentStructure","targetField":"governmentEffectiveness","operation":"add","value":2}],"previewEffects":{"stabilityImpact":"Steady administration"},"outcomeText":"The department runs smoothly under a familiar hand.","isAutoResolveDefault":true},{"id":"loyalist","label":"The party loyalist","description":"Reward a supporter and keep the party happy.","consequences":[{"targetModel":"Country","targetField":"publicApproval","operation":"add","value":1},{"targetModel":"GovernmentStructure","targetField":"corruptionIndex","operation":"add","value":1}],"previewEffects":{"publicApproval":1,"stabilityImpact":"Questions about patronage"},"outcomeText":"The party base cheers. Commentators ask what the new minister knows about the brief."},{"id":"expert","label":"The outside expert","description":"Bring in fresh knowledge from outside politics.","consequences":[{"targetModel":"GovernmentStructure","targetField":"governmentEffectiveness","operation":"add","value":1},{"targetModel":"InternalStabilityMetrics","targetField":"trustInGovernment","operation":"add","value":3}],"previewEffects":{"stabilityImpact":"Trust up"},"outcomeText":"The appointment is well received, though the new minister takes time to learn the politics."}]', true, CURRENT_TIMESTAMP) ON CONFLICT (slug) DO UPDATE SET "title" = EXCLUDED."title", "description" = EXCLUDED."description", "longDescription" = EXCLUDED."longDescription", "domain" = EXCLUDED."domain", "category" = EXCLUDED."category", "tags" = EXCLUDED."tags", "baseSeverity" = EXCLUDED."baseSeverity", "baseUrgency" = EXCLUDED."baseUrgency", "deadlineDaysBase" = EXCLUDED."deadlineDaysBase", "triggerConditions" = EXCLUDED."triggerConditions", "cooldownDays" = EXCLUDED."cooldownDays", "maxActivePerCountry" = EXCLUDED."maxActivePerCountry", "responseOptions" = EXCLUDED."responseOptions", "isActive" = EXCLUDED."isActive", "updatedAt" = EXCLUDED."updatedAt";
INSERT INTO national_issue_templates ("id", "slug", "title", "description", "longDescription", "domain", "category", "tags", "baseSeverity", "baseUrgency", "deadlineDaysBase", "triggerConditions", "cooldownDays", "maxActivePerCountry", "responseOptions", "isActive", "updatedAt") VALUES ('routine_national_festival', 'routine_national_festival', 'Planning the national festival', 'Organisers want to know how big {{countryName}}''s national day celebrations should be this year.', 'The national day falls in a few weeks. A full programme of parades, concerts and fireworks in {{capitalCity}} would cost real money. Smaller town events would cost little, and some backbenchers suggest skipping the celebrations altogether.', 'social', 'social', '["routine","culture"]', 'low', 30, NULL, '{"field":"currentPopulation","op":">=","value":0}', 35, 1, '[{"id":"grand","label":"A full celebration","description":"Parades, concerts and fireworks in the capital.","consequences":[{"targetModel":"Country","targetField":"publicApproval","operation":"add","value":3},{"targetModel":"InternalStabilityMetrics","targetField":"socialCohesion","operation":"add","value":2},{"targetModel":"Country","targetField":"totalDebtGDPRatio","operation":"add","value":0.3}],"previewEffects":{"publicApproval":3,"stabilityImpact":"Positive"},"outcomeText":"Crowds fill the streets of the capital. The fireworks are talked about for weeks."},{"id":"local","label":"Town events","description":"Let each town hold its own modest celebration.","consequences":[{"targetModel":"Country","targetField":"publicApproval","operation":"add","value":1},{"targetModel":"InternalStabilityMetrics","targetField":"socialCohesion","operation":"add","value":2}],"previewEffects":{"publicApproval":1},"outcomeText":"Village greens and town squares host fairs and picnics across the country.","isAutoResolveDefault":true},{"id":"skip","label":"Skip it this year","description":"Save the money and mark the day with a statement.","consequences":[{"targetModel":"Country","targetField":"publicApproval","operation":"subtract","value":2},{"targetModel":"Country","targetField":"totalDebtGDPRatio","operation":"subtract","value":0.3}],"previewEffects":{"publicApproval":-2},"outcomeText":"The day passes quietly. Many feel the government missed a chance to bring people together."}]', true, CURRENT_TIMESTAMP) ON CONFLICT (slug) DO UPDATE SET "title" = EXCLUDED."title", "description" = EXCLUDED."description", "longDescription" = EXCLUDED."longDescription", "domain" = EXCLUDED."domain", "category" = EXCLUDED."category", "tags" = EXCLUDED."tags", "baseSeverity" = EXCLUDED."baseSeverity", "baseUrgency" = EXCLUDED."baseUrgency", "deadlineDaysBase" = EXCLUDED."deadlineDaysBase", "triggerConditions" = EXCLUDED."triggerConditions", "cooldownDays" = EXCLUDED."cooldownDays", "maxActivePerCountry" = EXCLUDED."maxActivePerCountry", "responseOptions" = EXCLUDED."responseOptions", "isActive" = EXCLUDED."isActive", "updatedAt" = EXCLUDED."updatedAt";
INSERT INTO national_issue_templates ("id", "slug", "title", "description", "longDescription", "domain", "category", "tags", "baseSeverity", "baseUrgency", "deadlineDaysBase", "triggerConditions", "cooldownDays", "maxActivePerCountry", "responseOptions", "isActive", "updatedAt") VALUES ('routine_trade_delegation', 'routine_trade_delegation', 'A trade delegation asks for talks', 'Business leaders from {{partnerName}} want to meet {{countryName}}''s government about new deals.', 'The delegation represents firms in the {{sectorName}} sector. They hope for lower barriers and a visit from a senior minister. Domestic producers in the same sector are wary of new competition.', 'economic', 'economic', '["routine","trade"]', 'low', 30, NULL, '{"field":"currentPopulation","op":">=","value":0}', 28, 1, '[{"id":"open_talks","label":"Open formal talks","description":"Send a senior minister and negotiate in earnest.","consequences":[{"targetModel":"Country","targetField":"actualGdpGrowth","operation":"add","value":0.1},{"targetModel":"Country","targetField":"publicApproval","operation":"subtract","value":1}],"previewEffects":{"publicApproval":-1,"economicImpact":"Slightly faster growth"},"outcomeText":"The talks go well and new orders follow. Local producers grumble about the competition."},{"id":"listen","label":"Hear them out","description":"Host the delegation and promise to study their proposals.","consequences":[{"targetModel":"Country","targetField":"actualGdpGrowth","operation":"add","value":0.05}],"previewEffects":{"economicImpact":"Small gain"},"outcomeText":"The delegation leaves with a few modest agreements and an invitation to return.","isAutoResolveDefault":true},{"id":"protect","label":"Protect local producers","description":"Decline new concessions for now.","consequences":[{"targetModel":"Country","targetField":"publicApproval","operation":"add","value":1},{"targetModel":"Country","targetField":"actualGdpGrowth","operation":"subtract","value":0.05}],"previewEffects":{"publicApproval":1,"economicImpact":"Small cost"},"outcomeText":"Domestic firms thank the government. The visitors take their business elsewhere."}]', true, CURRENT_TIMESTAMP) ON CONFLICT (slug) DO UPDATE SET "title" = EXCLUDED."title", "description" = EXCLUDED."description", "longDescription" = EXCLUDED."longDescription", "domain" = EXCLUDED."domain", "category" = EXCLUDED."category", "tags" = EXCLUDED."tags", "baseSeverity" = EXCLUDED."baseSeverity", "baseUrgency" = EXCLUDED."baseUrgency", "deadlineDaysBase" = EXCLUDED."deadlineDaysBase", "triggerConditions" = EXCLUDED."triggerConditions", "cooldownDays" = EXCLUDED."cooldownDays", "maxActivePerCountry" = EXCLUDED."maxActivePerCountry", "responseOptions" = EXCLUDED."responseOptions", "isActive" = EXCLUDED."isActive", "updatedAt" = EXCLUDED."updatedAt";
INSERT INTO national_issue_templates ("id", "slug", "title", "description", "longDescription", "domain", "category", "tags", "baseSeverity", "baseUrgency", "deadlineDaysBase", "triggerConditions", "cooldownDays", "maxActivePerCountry", "responseOptions", "isActive", "updatedAt") VALUES ('routine_national_census', 'routine_national_census', 'Running the national census', 'The statistics office says {{countryName}}''s population figures are getting out of date.', 'Good figures help every ministry plan. A full census means hiring thousands of enumerators. A sample survey is cheaper but less precise, and the office warns that postponing again will make planning harder.', 'political', 'governance', '["routine","statistics"]', 'low', 30, NULL, '{"field":"currentPopulation","op":">=","value":0}', 42, 1, '[{"id":"full","label":"A full census","description":"Count every household.","consequences":[{"targetModel":"GovernmentStructure","targetField":"governmentEffectiveness","operation":"add","value":2},{"targetModel":"Country","targetField":"totalDebtGDPRatio","operation":"add","value":0.3}],"previewEffects":{"economicImpact":"Better planning, small cost"},"outcomeText":"Enumerators knock on every door. The new figures reshape several ministry plans."},{"id":"sample","label":"A sample survey","description":"Survey a representative share of households.","consequences":[{"targetModel":"GovernmentStructure","targetField":"governmentEffectiveness","operation":"add","value":1}],"previewEffects":{"stabilityImpact":"Modest improvement"},"outcomeText":"The survey gives a usable picture at a fraction of the cost.","isAutoResolveDefault":true},{"id":"postpone","label":"Postpone it","description":"Wait until the budget is less tight.","consequences":[{"targetModel":"GovernmentStructure","targetField":"governmentEffectiveness","operation":"subtract","value":1}],"previewEffects":{"stabilityImpact":"Planning gets harder"},"outcomeText":"Ministries keep working from old numbers, and some programmes miss their targets."}]', true, CURRENT_TIMESTAMP) ON CONFLICT (slug) DO UPDATE SET "title" = EXCLUDED."title", "description" = EXCLUDED."description", "longDescription" = EXCLUDED."longDescription", "domain" = EXCLUDED."domain", "category" = EXCLUDED."category", "tags" = EXCLUDED."tags", "baseSeverity" = EXCLUDED."baseSeverity", "baseUrgency" = EXCLUDED."baseUrgency", "deadlineDaysBase" = EXCLUDED."deadlineDaysBase", "triggerConditions" = EXCLUDED."triggerConditions", "cooldownDays" = EXCLUDED."cooldownDays", "maxActivePerCountry" = EXCLUDED."maxActivePerCountry", "responseOptions" = EXCLUDED."responseOptions", "isActive" = EXCLUDED."isActive", "updatedAt" = EXCLUDED."updatedAt";
INSERT INTO national_issue_templates ("id", "slug", "title", "description", "longDescription", "domain", "category", "tags", "baseSeverity", "baseUrgency", "deadlineDaysBase", "triggerConditions", "cooldownDays", "maxActivePerCountry", "responseOptions", "isActive", "updatedAt") VALUES ('routine_civil_service_pay', 'routine_civil_service_pay', 'The civil service pay review', 'Public sector unions in {{countryName}} have submitted their annual pay claim.', 'Rising living costs have eaten into civil service pay. The unions want a rise in line with prices. The treasury would prefer a freeze, and some advisers suggest tying part of any rise to performance.', 'political', 'governance', '["routine","civil-service"]', 'low', 30, NULL, '{"field":"currentPopulation","op":">=","value":0}', 35, 1, '[{"id":"match_prices","label":"Match the cost of living","description":"Give a rise in line with prices.","consequences":[{"targetModel":"GovernmentStructure","targetField":"governmentEffectiveness","operation":"add","value":2},{"targetModel":"Country","targetField":"totalDebtGDPRatio","operation":"add","value":0.5}],"previewEffects":{"economicImpact":"A little more debt"},"outcomeText":"The unions accept. Morale in the ministries improves."},{"id":"performance","label":"Tie part to performance","description":"A smaller rise plus bonuses for teams that hit their targets.","consequences":[{"targetModel":"GovernmentStructure","targetField":"governmentEffectiveness","operation":"add","value":1},{"targetModel":"Country","targetField":"totalDebtGDPRatio","operation":"add","value":0.3}],"previewEffects":{"economicImpact":"Small cost"},"outcomeText":"The scheme gets a cautious welcome. The first bonuses are paid at year end.","isAutoResolveDefault":true},{"id":"freeze","label":"Freeze pay","description":"Hold pay flat for another year.","consequences":[{"targetModel":"GovernmentStructure","targetField":"governmentEffectiveness","operation":"subtract","value":1},{"targetModel":"Country","targetField":"totalDebtGDPRatio","operation":"subtract","value":0.3}],"previewEffects":{"economicImpact":"Small saving"},"outcomeText":"The treasury saves money. Some experienced staff leave for private jobs."}]', true, CURRENT_TIMESTAMP) ON CONFLICT (slug) DO UPDATE SET "title" = EXCLUDED."title", "description" = EXCLUDED."description", "longDescription" = EXCLUDED."longDescription", "domain" = EXCLUDED."domain", "category" = EXCLUDED."category", "tags" = EXCLUDED."tags", "baseSeverity" = EXCLUDED."baseSeverity", "baseUrgency" = EXCLUDED."baseUrgency", "deadlineDaysBase" = EXCLUDED."deadlineDaysBase", "triggerConditions" = EXCLUDED."triggerConditions", "cooldownDays" = EXCLUDED."cooldownDays", "maxActivePerCountry" = EXCLUDED."maxActivePerCountry", "responseOptions" = EXCLUDED."responseOptions", "isActive" = EXCLUDED."isActive", "updatedAt" = EXCLUDED."updatedAt";
INSERT INTO national_issue_templates ("id", "slug", "title", "description", "longDescription", "domain", "category", "tags", "baseSeverity", "baseUrgency", "deadlineDaysBase", "triggerConditions", "cooldownDays", "maxActivePerCountry", "responseOptions", "isActive", "updatedAt") VALUES ('routine_school_curriculum', 'routine_school_curriculum', 'Updating the school curriculum', 'The education ministry''s ten-year curriculum review is ready for a decision.', 'Teachers, employers and parents all had their say. The review offers a choice of emphasis: practical and technical skills, civics and national history, or keeping the current curriculum with small fixes.', 'social', 'social', '["routine","education"]', 'low', 30, NULL, '{"field":"currentPopulation","op":">=","value":0}', 42, 1, '[{"id":"skills","label":"Practical and technical skills","description":"More mathematics, science and vocational training.","consequences":[{"targetModel":"Country","targetField":"literacyRate","operation":"add","value":0.5},{"targetModel":"Country","targetField":"actualGdpGrowth","operation":"add","value":0.05}],"previewEffects":{"economicImpact":"A better trained workforce"},"outcomeText":"Employers welcome the change. New workshops open in schools across the country."},{"id":"civics","label":"Civics and history","description":"Teach how the country is governed and where it came from.","consequences":[{"targetModel":"InternalStabilityMetrics","targetField":"socialCohesion","operation":"add","value":2}],"previewEffects":{"stabilityImpact":"Positive"},"outcomeText":"Pupils start debating clubs and visit the national archives."},{"id":"minor","label":"Small fixes only","description":"Keep what works and update outdated material.","consequences":[{"targetModel":"Country","targetField":"publicApproval","operation":"add","value":1}],"previewEffects":{"publicApproval":1},"outcomeText":"Teachers are relieved not to rewrite their lessons. Textbooks get a refresh.","isAutoResolveDefault":true}]', true, CURRENT_TIMESTAMP) ON CONFLICT (slug) DO UPDATE SET "title" = EXCLUDED."title", "description" = EXCLUDED."description", "longDescription" = EXCLUDED."longDescription", "domain" = EXCLUDED."domain", "category" = EXCLUDED."category", "tags" = EXCLUDED."tags", "baseSeverity" = EXCLUDED."baseSeverity", "baseUrgency" = EXCLUDED."baseUrgency", "deadlineDaysBase" = EXCLUDED."deadlineDaysBase", "triggerConditions" = EXCLUDED."triggerConditions", "cooldownDays" = EXCLUDED."cooldownDays", "maxActivePerCountry" = EXCLUDED."maxActivePerCountry", "responseOptions" = EXCLUDED."responseOptions", "isActive" = EXCLUDED."isActive", "updatedAt" = EXCLUDED."updatedAt";
INSERT INTO national_issue_templates ("id", "slug", "title", "description", "longDescription", "domain", "category", "tags", "baseSeverity", "baseUrgency", "deadlineDaysBase", "triggerConditions", "cooldownDays", "maxActivePerCountry", "responseOptions", "isActive", "updatedAt") VALUES ('routine_policing_plan', 'routine_policing_plan', 'Agreeing the annual policing plan', 'Police chiefs have sent {{officialTitle}} their plan for the coming year.', 'Crime is neither rising nor falling much. The chiefs offer a choice between more neighbourhood officers, more spending on investigations and equipment, or keeping the current plan.', 'social', 'security', '["routine","policing"]', 'low', 30, NULL, '{"field":"currentPopulation","op":">=","value":0}', 35, 1, '[{"id":"neighbourhood","label":"Neighbourhood officers","description":"Put more officers on local beats.","consequences":[{"targetModel":"InternalStabilityMetrics","targetField":"trustInGovernment","operation":"add","value":3},{"targetModel":"Country","targetField":"totalDebtGDPRatio","operation":"add","value":0.3}],"previewEffects":{"stabilityImpact":"Trust up"},"outcomeText":"Familiar faces return to the high streets. Residents say they feel safer."},{"id":"investigations","label":"Investigations and equipment","description":"Fund detectives, forensics and modern equipment.","consequences":[{"targetModel":"InternalStabilityMetrics","targetField":"policingEffectiveness","operation":"add","value":3},{"targetModel":"InternalStabilityMetrics","targetField":"crimeRate","operation":"subtract","value":1},{"targetModel":"Country","targetField":"totalDebtGDPRatio","operation":"add","value":0.3}],"previewEffects":{"stabilityImpact":"Less crime"},"outcomeText":"Clearance rates improve over the year as new labs come online."},{"id":"steady","label":"Keep the current plan","description":"No changes this year.","consequences":[],"previewEffects":{},"outcomeText":"Policing carries on as before.","isAutoResolveDefault":true}]', true, CURRENT_TIMESTAMP) ON CONFLICT (slug) DO UPDATE SET "title" = EXCLUDED."title", "description" = EXCLUDED."description", "longDescription" = EXCLUDED."longDescription", "domain" = EXCLUDED."domain", "category" = EXCLUDED."category", "tags" = EXCLUDED."tags", "baseSeverity" = EXCLUDED."baseSeverity", "baseUrgency" = EXCLUDED."baseUrgency", "deadlineDaysBase" = EXCLUDED."deadlineDaysBase", "triggerConditions" = EXCLUDED."triggerConditions", "cooldownDays" = EXCLUDED."cooldownDays", "maxActivePerCountry" = EXCLUDED."maxActivePerCountry", "responseOptions" = EXCLUDED."responseOptions", "isActive" = EXCLUDED."isActive", "updatedAt" = EXCLUDED."updatedAt";
INSERT INTO national_issue_templates ("id", "slug", "title", "description", "longDescription", "domain", "category", "tags", "baseSeverity", "baseUrgency", "deadlineDaysBase", "triggerConditions", "cooldownDays", "maxActivePerCountry", "responseOptions", "isActive", "updatedAt") VALUES ('routine_tourism_campaign', 'routine_tourism_campaign', 'Promoting the country abroad', 'The tourism board has proposals to bring more visitors to {{countryName}}.', 'Hotels and restaurants report a steady season. The board suggests an international advertising campaign, a smaller programme of regional fairs, or leaving promotion to the industry itself.', 'economic', 'economic', '["routine","tourism"]', 'low', 30, NULL, '{"field":"currentPopulation","op":">=","value":0}', 35, 1, '[{"id":"campaign","label":"An international campaign","description":"Advertise the country''s sights in major markets.","consequences":[{"targetModel":"Country","targetField":"actualGdpGrowth","operation":"add","value":0.1},{"targetModel":"Country","targetField":"totalDebtGDPRatio","operation":"add","value":0.3}],"previewEffects":{"economicImpact":"More visitors, small cost"},"outcomeText":"Bookings rise the following season, especially in the coastal towns."},{"id":"fairs","label":"Regional fairs","description":"Fund local festivals that draw visitors to smaller towns.","consequences":[{"targetModel":"Country","targetField":"publicApproval","operation":"add","value":1},{"targetModel":"Country","targetField":"actualGdpGrowth","operation":"add","value":0.05}],"previewEffects":{"publicApproval":1},"outcomeText":"Market towns enjoy busy weekends and full guesthouses.","isAutoResolveDefault":true},{"id":"industry","label":"Leave it to the industry","description":"Spend nothing and let businesses promote themselves.","consequences":[{"targetModel":"Country","targetField":"totalDebtGDPRatio","operation":"subtract","value":0.2}],"previewEffects":{"economicImpact":"Small saving"},"outcomeText":"The season goes much as the last one did."}]', true, CURRENT_TIMESTAMP) ON CONFLICT (slug) DO UPDATE SET "title" = EXCLUDED."title", "description" = EXCLUDED."description", "longDescription" = EXCLUDED."longDescription", "domain" = EXCLUDED."domain", "category" = EXCLUDED."category", "tags" = EXCLUDED."tags", "baseSeverity" = EXCLUDED."baseSeverity", "baseUrgency" = EXCLUDED."baseUrgency", "deadlineDaysBase" = EXCLUDED."deadlineDaysBase", "triggerConditions" = EXCLUDED."triggerConditions", "cooldownDays" = EXCLUDED."cooldownDays", "maxActivePerCountry" = EXCLUDED."maxActivePerCountry", "responseOptions" = EXCLUDED."responseOptions", "isActive" = EXCLUDED."isActive", "updatedAt" = EXCLUDED."updatedAt";
INSERT INTO national_issue_templates ("id", "slug", "title", "description", "longDescription", "domain", "category", "tags", "baseSeverity", "baseUrgency", "deadlineDaysBase", "triggerConditions", "cooldownDays", "maxActivePerCountry", "responseOptions", "isActive", "updatedAt") VALUES ('routine_national_parks', 'routine_national_parks', 'Looking after the national parks', 'Park rangers say visitor numbers are up and the trails need work.', 'The parks service has three proposals: buy more land to protect, open new visitor centres and trails, or keep budgets flat and ask volunteers to help with upkeep.', 'environmental', 'infrastructure', '["routine","parks"]', 'low', 30, NULL, '{"field":"currentPopulation","op":">=","value":0}', 42, 1, '[{"id":"protect","label":"Protect more land","description":"Buy and protect neighbouring forest and wetland.","consequences":[{"targetModel":"Country","targetField":"publicApproval","operation":"add","value":2},{"targetModel":"Country","targetField":"totalDebtGDPRatio","operation":"add","value":0.3}],"previewEffects":{"publicApproval":2},"outcomeText":"The parks grow by several thousand hectares. Conservation groups are delighted."},{"id":"visitors","label":"New trails and visitor centres","description":"Make the parks easier to visit.","consequences":[{"targetModel":"Country","targetField":"actualGdpGrowth","operation":"add","value":0.05},{"targetModel":"Country","targetField":"infrastructureRating","operation":"add","value":1}],"previewEffects":{"economicImpact":"More visitors"},"outcomeText":"New paths and centres open by summer, and nearby villages see more trade.","isAutoResolveDefault":true},{"id":"volunteers","label":"Ask for volunteers","description":"Keep budgets flat and recruit volunteers for upkeep.","consequences":[{"targetModel":"InternalStabilityMetrics","targetField":"socialCohesion","operation":"add","value":2}],"previewEffects":{"stabilityImpact":"Positive"},"outcomeText":"Hundreds sign up for weekend work parties. Some trails still wait for repairs."}]', true, CURRENT_TIMESTAMP) ON CONFLICT (slug) DO UPDATE SET "title" = EXCLUDED."title", "description" = EXCLUDED."description", "longDescription" = EXCLUDED."longDescription", "domain" = EXCLUDED."domain", "category" = EXCLUDED."category", "tags" = EXCLUDED."tags", "baseSeverity" = EXCLUDED."baseSeverity", "baseUrgency" = EXCLUDED."baseUrgency", "deadlineDaysBase" = EXCLUDED."deadlineDaysBase", "triggerConditions" = EXCLUDED."triggerConditions", "cooldownDays" = EXCLUDED."cooldownDays", "maxActivePerCountry" = EXCLUDED."maxActivePerCountry", "responseOptions" = EXCLUDED."responseOptions", "isActive" = EXCLUDED."isActive", "updatedAt" = EXCLUDED."updatedAt";
INSERT INTO national_issue_templates ("id", "slug", "title", "description", "longDescription", "domain", "category", "tags", "baseSeverity", "baseUrgency", "deadlineDaysBase", "triggerConditions", "cooldownDays", "maxActivePerCountry", "responseOptions", "isActive", "updatedAt") VALUES ('routine_honours_list', 'routine_honours_list', 'Approving the annual honours list', 'The honours committee has sent its recommendations for {{currentYear}}.', 'The list is a chance to recognise service to the country. This year the committee asks whether the emphasis should fall on community volunteers, on business and science, or on public servants.', 'political', 'governance', '["routine","honours"]', 'low', 30, NULL, '{"field":"currentPopulation","op":">=","value":0}', 42, 1, '[{"id":"volunteers","label":"Community volunteers","description":"Honour carers, coaches and local organisers.","consequences":[{"targetModel":"InternalStabilityMetrics","targetField":"socialCohesion","operation":"add","value":2},{"targetModel":"Country","targetField":"publicApproval","operation":"add","value":1}],"previewEffects":{"publicApproval":1,"stabilityImpact":"Positive"},"outcomeText":"Local papers run stories about the honourees for weeks.","isAutoResolveDefault":true},{"id":"enterprise","label":"Business and science","description":"Honour founders, inventors and researchers.","consequences":[{"targetModel":"Country","targetField":"actualGdpGrowth","operation":"add","value":0.05}],"previewEffects":{"economicImpact":"A small boost to confidence"},"outcomeText":"The list is praised in business circles. A few honourees use the moment to announce new investment."},{"id":"public_servants","label":"Public servants","description":"Honour long-serving nurses, teachers and officials.","consequences":[{"targetModel":"GovernmentStructure","targetField":"governmentEffectiveness","operation":"add","value":1}],"previewEffects":{"stabilityImpact":"Morale up"},"outcomeText":"Staff across the public sector take quiet pride in the recognition."}]', true, CURRENT_TIMESTAMP) ON CONFLICT (slug) DO UPDATE SET "title" = EXCLUDED."title", "description" = EXCLUDED."description", "longDescription" = EXCLUDED."longDescription", "domain" = EXCLUDED."domain", "category" = EXCLUDED."category", "tags" = EXCLUDED."tags", "baseSeverity" = EXCLUDED."baseSeverity", "baseUrgency" = EXCLUDED."baseUrgency", "deadlineDaysBase" = EXCLUDED."deadlineDaysBase", "triggerConditions" = EXCLUDED."triggerConditions", "cooldownDays" = EXCLUDED."cooldownDays", "maxActivePerCountry" = EXCLUDED."maxActivePerCountry", "responseOptions" = EXCLUDED."responseOptions", "isActive" = EXCLUDED."isActive", "updatedAt" = EXCLUDED."updatedAt";
